    document.querySelectorAll('[data-carousel]').forEach(carousel=>{const viewport=carousel.querySelector('.carousel-viewport'),track=carousel.querySelector('.carousel-track'),cards=[...track.children],counter=carousel.querySelector('.counter strong'),total=carousel.querySelector('.counter-total'),prev=carousel.querySelector('[data-prev]'),next=carousel.querySelector('[data-next]');let index=0,startX=0,lastX=0,dragging=false;const visible=()=>{if(track.classList.contains('gallery-track'))return 1;if(cards[0].classList.contains('quote-card'))return innerWidth>=700?3:1;if(track.classList.contains('environment-track'))return innerWidth>=700?3:1;return innerWidth>=700?3:1};const update=()=>{const gap=parseFloat(getComputedStyle(track).gap)||0,step=cards[0].getBoundingClientRect().width+gap,max=Math.max(0,cards.length-visible());index=Math.min(index,max);track.style.transform=`translateX(${-step*index}px)`;if(counter)counter.textContent=String(index+1).padStart(2,'0');if(total)total.textContent=String(cards.length).padStart(2,'0')};prev?.addEventListener('click',()=>{index=Math.max(0,index-1);update()});next?.addEventListener('click',()=>{index=Math.min(cards.length-visible(),index+1);update()});viewport.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){index=Math.min(cards.length-visible(),index+1);update()}if(event.key==='ArrowLeft'){index=Math.max(0,index-1);update()}});viewport.addEventListener('pointerdown',event=>{startX=lastX=event.clientX;dragging=true;viewport.classList.add('dragging');viewport.setPointerCapture(event.pointerId)});viewport.addEventListener('pointermove',event=>{if(dragging)lastX=event.clientX});viewport.addEventListener('pointerup',()=>{if(!dragging)return;dragging=false;viewport.classList.remove('dragging');if(Math.abs(lastX-startX)>35){index=Math.max(0,Math.min(cards.length-visible(),index+(lastX<startX?1:-1)));update()}});viewport.addEventListener('pointercancel',()=>{dragging=false;viewport.classList.remove('dragging')});addEventListener('resize',update);update()});
