    (()=>{
      const galleries=[...document.querySelectorAll('.before-after-carousel')];
      const dialog=document.querySelector('#case-lightbox'),lightboxImg=document.querySelector('#lightbox-image'),caption=document.querySelector('#lightbox-caption');
      let activeGallery=null,activeIndex=0,returnFocus=null,dragging=false,dragged=false,startX=0,startScroll=0,scale=1,panX=0,panY=0,lastX=0,lastY=0,pinchStart=0;
      const cardsFor=g=>[...g.querySelectorAll('.before-after-card')];
      galleries.forEach(g=>{
        const cards=cardsFor(g),counter=g.parentElement.querySelector('.before-after-counter strong'),prev=g.parentElement.querySelector('[data-gallery-prev]'),next=g.parentElement.querySelector('[data-gallery-next]');
        const nearest=()=>{let best=0,distance=Infinity;cards.forEach((card,i)=>{const d=Math.abs((card.offsetLeft-cards[0].offsetLeft)-g.scrollLeft);if(d<distance){distance=d;best=i}});return best};
        const goTo=i=>{const target=Math.max(0,Math.min(cards.length-1,i));g.scrollTo({left:cards[target].offsetLeft-cards[0].offsetLeft,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};
        const update=()=>{counter.textContent=String(nearest()+1).padStart(2,'0')};
        g.addEventListener('scroll',update,{passive:true});addEventListener('resize',update);
        prev.addEventListener('click',()=>goTo(nearest()-1));
        next.addEventListener('click',()=>goTo(nearest()+1));
        g.addEventListener('keydown',e=>{if(e.key==='ArrowRight')goTo(nearest()+1);if(e.key==='ArrowLeft')goTo(nearest()-1)});
        g.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse')return;dragging=true;dragged=false;startX=e.clientX;startScroll=g.scrollLeft;g.classList.add('is-dragging');g.setPointerCapture(e.pointerId)});
        g.addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-startX;if(Math.abs(dx)>5)dragged=true;if(dragged)g.scrollLeft=startScroll-dx});
        const end=()=>{if(!dragging)return;dragging=false;g.classList.remove('is-dragging');if(dragged)setTimeout(()=>dragged=false,0)};g.addEventListener('pointerup',end);g.addEventListener('pointercancel',end);
        g.addEventListener('click',e=>{if(dragged){e.preventDefault();e.stopImmediatePropagation();dragged=false}},true);
        cards.forEach((card,i)=>card.addEventListener('click',()=>{if(dragged)return;activeGallery=g;activeIndex=i;returnFocus=card;showCase();dialog.showModal();dialog.querySelector('.lightbox-close').focus()}));update();
      });
      const currentCards=()=>cardsFor(activeGallery);
      const applyZoom=()=>{lightboxImg.style.transform=`translate(${panX}px,${panY}px) scale(${scale})`};
      const showCase=()=>{const cards=currentCards();activeIndex=(activeIndex+cards.length)%cards.length;const img=cards[activeIndex].querySelector('img');lightboxImg.src=img.src;lightboxImg.alt=img.alt;scale=1;panX=panY=0;applyZoom();caption.textContent=`${img.alt}. Cada caso tem suas particularidades.`};
      const close=()=>dialog.close();dialog.querySelector('.lightbox-close').addEventListener('click',close);dialog.querySelector('.lightbox-prev').addEventListener('click',()=>{activeIndex--;showCase()});dialog.querySelector('.lightbox-next').addEventListener('click',()=>{activeIndex++;showCase()});dialog.addEventListener('click',e=>{if(e.target===dialog)close()});dialog.addEventListener('close',()=>{lightboxImg.removeAttribute('src');if(returnFocus?.isConnected)returnFocus.focus();activeGallery=null});
      document.addEventListener('keydown',e=>{if(!dialog.open)return;if(e.key==='Escape')close();if(e.key==='ArrowLeft'){activeIndex--;showCase()}if(e.key==='ArrowRight'){activeIndex++;showCase()}});
      let touchStartX=0;lightboxImg.addEventListener('touchstart',e=>{if(e.touches.length===2){pinchStart=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);lightboxImg.dataset.zoomBase=String(scale);e.preventDefault()}else if(e.touches.length===1){touchStartX=lastX=e.touches[0].clientX;lastY=e.touches[0].clientY}},{passive:false});
      lightboxImg.addEventListener('touchmove',e=>{if(e.touches.length===2&&pinchStart){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);scale=Math.max(1,Math.min(4,Number(lightboxImg.dataset.zoomBase||1)*d/pinchStart));applyZoom();e.preventDefault()}else if(e.touches.length===1&&scale>1){panX+=e.touches[0].clientX-lastX;panY+=e.touches[0].clientY-lastY;lastX=e.touches[0].clientX;lastY=e.touches[0].clientY;applyZoom();e.preventDefault()}},{passive:false});
      lightboxImg.addEventListener('touchend',e=>{if(e.touches.length<2){pinchStart=0;delete lightboxImg.dataset.zoomBase}if(e.changedTouches.length&&scale===1){const dx=e.changedTouches[0].clientX-touchStartX;if(Math.abs(dx)>55){activeIndex+=dx<0?1:-1;showCase()}}},{passive:true});
    })();
  
    

