function renderGrid(){const intent=INTENTS[selectedIntent],title=w.querySelector('#intent-options-title');title.textContent='Possibilidades para '+(intent?.label||'sua avaliação');w.querySelector('#selection-count').hidden=false;if(selectedIntent==='rosto'){grid.innerHTML="<div class=\"face-map-wrap\"><svg class=\"face-map\" viewBox=\"0 0 240 300\" role=\"img\" aria-label=\"Mapa interativo do rosto\"><path class=\"face-outline\" d=\"M120 18c-45 0-74 36-74 91 0 77 37 151 74 166 37-15 74-89 74-166 0-55-29-91-74-91Z\"/><path class=\"face-feature\" d=\"M75 111q18-12 36 0m18 0q18-12 36 0M85 149q15 9 30 0m10 0q15 9 30 0m-50 39q25 16 50 0m-39 29q14 7 28 0\"/><g class=\"face-zone\" tabindex=\"0\" role=\"button\" aria-label=\"Testa e entre as sobrancelhas\" aria-pressed=\"false\" data-zone=\"Testa e entre as sobrancelhas\" data-procedures=\"Botox (toxina botulínica)\"><ellipse cx=\"120\" cy=\"83\" rx=\"49\" ry=\"25\"/></g><g class=\"face-zone\" tabindex=\"0\" role=\"button\" aria-label=\"Bochechas e contorno facial\" aria-pressed=\"false\" data-zone=\"Bochechas e contorno facial\" data-procedures=\"Preenchimentos facial e labial|Bioestimuladores\"><ellipse cx=\"120\" cy=\"159\" rx=\"70\" ry=\"30\"/></g><g class=\"face-zone\" tabindex=\"0\" role=\"button\" aria-label=\"Lábios\" aria-pressed=\"false\" data-zone=\"Lábios\" data-procedures=\"Preenchimentos facial e labial\"><ellipse cx=\"120\" cy=\"192\" rx=\"30\" ry=\"12\"/></g></svg><div class=\"face-map-help\"><strong id=\"face-zone-title\">Toque em uma área</strong><p id=\"face-zone-description\">Veja quais possibilidades podem ser conversadas na avaliação.</p><div id=\"face-zone-options\" class=\"face-zone-options\"></div></div></div><p class=\"face-map-note\">Toque em uma área para conhecer possibilidades de cuidado. A equipe explica o que faz sentido para você.</p>";const zones=[...grid.querySelectorAll('.face-zone')];const chooseZone=zone=>{selectedFaceZone=zone.dataset.zone;areas=new Set(['rosto',selectedFaceZone]);zones.forEach(z=>{const active=z===zone;z.classList.toggle('is-selected',active);z.setAttribute('aria-pressed',String(active))});w.querySelector('#face-zone-title').textContent=selectedFaceZone;const names=zone.dataset.procedures.split('|');const list=w.querySelector('#face-zone-options');list.innerHTML=names.map(name=>'<button type="button" class="face-option" data-name="'+name+'" aria-pressed="'+chosen.has(name)+'">'+name+' <span>'+(chosen.has(name)?'✓':'＋')+'</span></button>').join('');list.querySelectorAll('[data-name]').forEach(button=>button.onclick=()=>{const name=button.dataset.name;chosen.has(name)?chosen.delete(name):chosen.add(name);button.setAttribute('aria-pressed',String(chosen.has(name)));button.querySelector('span').textContent=chosen.has(name)?'✓':'＋';count();buzz()})};zones.forEach(zone=>{zone.addEventListener('click',()=>chooseZone(zone));zone.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();chooseZone(zone)}})});return}const items=PROCEDIMENTOS.filter(p=>intent&&intent.categories.includes(p.cat));if(!items.length){grid.innerHTML='<p class="intent-empty">Vamos começar pela sua necessidade. A equipe conversa com você e orienta a avaliação.</p>';w.querySelector('#selection-count').hidden=true;return}grid.innerHTML=items.map(p=>'<button type="button" class="procedure-card" data-name="'+p.nome+'" aria-pressed="'+chosen.has(p.nome)+'"><span class="procedure-icon" aria-hidden="true">'+p.icon+'</span><strong>'+p.nome+'</strong><small>'+p.desc+'</small><span class="procedure-check">'+(chosen.has(p.nome)?'✓':'')+'</span></button>').join('');grid.querySelectorAll('[data-name]').forEach(b=>b.onclick=()=>{const n=b.dataset.name;chosen.has(n)?chosen.delete(n):chosen.add(n);b.setAttribute('aria-pressed',String(chosen.has(n)));b.querySelector('.procedure-check').textContent=chosen.has(n)?'✓':'';count();buzz()});count()}
