function renderPeriod(){w.querySelector('.flexible-preferences').hidden=period!=='Horário flexível';w.querySelector('#hours-note').hidden=!(prefs.has('Sábado')||prefs.has('Depois das 18h'));pc.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.period===period)))}
function message(){return 'Olá! Vi o site da Dra Izabelle e gostaria de saber mais sobre uma avaliação. Sou '+(w.querySelector('#visitor-name').value.trim()||'não informado')+'.\nObjetivo: '+([...areas].join(', ')||(unsure?'Não sei por onde começar':'A definir na avaliação'))+'\nPossibilidades de interesse: '+([...chosen].join(', ')||(unsure?'Prefiro conversar sobre uma avaliação':'A definir na avaliação'))+'\nMelhor período: '+(period||'A combinar')+(prefs.size?' ('+[...prefs].join(', ')+')':'')+'\nGostaria de agendar uma avaliação.'}
function summary(){w.querySelector('#summary-procedures').textContent=[...chosen].join(', ')||(unsure?'A conversar durante a avaliação':'A definir na avaliação');w.querySelector('#summary-areas').textContent=[...areas].join(', ')||(unsure?'Não sei por onde começar':'A definir na avaliação');w.querySelector('#summary-period').textContent=period+(prefs.size?' · '+[...prefs].join(', '):'');w.querySelector('#wizard-whatsapp').href='https://wa.me/553190967816?text='+encodeURIComponent(message())}
w.querySelector('#visitor-name').oninput=()=>{if(step===5)summary()};w.querySelector('#copy-summary').onclick=async e=>{try{await navigator.clipboard.writeText(message());e.currentTarget.textContent='Resumo copiado ✓'}catch{e.currentTarget.textContent='Não foi possível copiar'}};
let celebrated=false;function confetti(){if(celebrated||matchMedia('(prefers-reduced-motion: reduce)').matches)return;celebrated=true;const layer=w.querySelector('#confetti-layer');for(let i=0;i<16;i++){const bit=document.createElement('i');bit.className='confetti-bit';bit.style.left=(5+Math.random()*90)+'%';bit.style.animationDelay=(Math.random()*.3)+'s';layer.append(bit)}setTimeout(()=>layer.replaceChildren(),1900)}
render();
